WITH base AS (SELECT *, COALESCE(level, 'unassigned') AS level_filled FROM employees WHERE hire_date > DATE '2023-05-13' AND job_title IS NOT NULL AND full_name IS NOT NULL), ranked AS (SELECT * FROM base QUALIFY ROW_NUMBER() OVER (PARTITION BY level ORDER BY hire_date DESC NULLS LAST, id) = 1), with_dims AS (SELECT src.*, b.full_name AS employee_full_name, b.hire_date AS employee_hire_date, b.level AS employee_level FROM ranked src LEFT JOIN employees b ON src.manager_id = b.id), metrics AS (SELECT *, LAG(salary, 1, 0) OVER w_part AS prev_salary, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id), 4) AS salary_share FROM with_dims WINDOW w_part AS (PARTITION BY dept_id ORDER BY salary, id)) SELECT dept_id, job_title, SIZE(COLLECT_SET(level)) AS num_levels, STDDEV_SAMP(salary) AS salary_stddev, GROUPING(dept_id) AS grouping_id FROM metrics GROUP BY ROLLUP (dept_id, job_title) ORDER BY num_levels DESC NULLS LAST;
